export const ToggleButton = ({ checked, onChange, size = 24, className = '' }) => (
  <button
    type="button"
    onClick={() => onChange(!checked)}
    className={className}
    style={{
      width: size * 2,
      height: size,
      borderRadius: size / 2,
      background: checked ? '#8B5CF6' : '#CBD5E1',
      border: 'none',
      cursor: 'pointer',
      position: 'relative',
      transition: 'background 0.3s ease',
      padding: 2,
    }}
  >
    <div
      style={{
        width: size - 4,
        height: size - 4,
        borderRadius: (size - 4) / 2,
        background: '#FFFFFF',
        position: 'absolute',
        top: 2,
        left: checked ? size + 2 : 2,
        transition: 'left 0.3s ease',
        boxShadow: '0 2px 4px rgba(0,0,0,0.2)',
      }}
    />
  </button>
);
